(()=>{const e=document.getElementById("p5-container");window.hand_index=Math.floor(5*fxrand()),window.elem_index=Math.floor(3*fxrand()),window.back_index=Math.floor(3*fxrand()),window.face_color=[Math.floor(255*fxrand()),Math.floor(0+255*fxrand()),Math.floor(0+255*fxrand())];let n=[{hand:"Fist",elems:["Bandage","Brass knuckles","Chain"]},{hand:"Love",elems:["Broken heart","Evil heart","Heart"]},{hand:"Ok",elems:["Smile","Angry","Sad"]},{hand:"Peace",elems:["Green","Rainbow","Pink"]},{hand:"Punk",elems:["Thorns","Inscription","Rivets"]}];window.$fxhashFeatures={Hand:n[window.hand_index].hand,"Litte object":n[window.hand_index].elems[window.elem_index],"Background type":"B"+window.hand_index+"T"+window.back_index,"Hand color":`${window.face_color[0]}, ${window.face_color[1]}, ${window.face_color[2]}`},new p5((e=>{e.preload=function(){e.hand_img=e.loadImages(5,"r"),e.elem_img=e.loadImages(3,"r"+(window.hand_index+1)),e.back_img=e.loadImages(5,"b"),e.bb_img=e.loadImages(3,"b"+(window.hand_index+1))},e.loadImages=function(n,a="",o=".png"){let d=[];for(let i=1;i<=n;i+=1){let n="img/"+a+i+o,r=e.loadImage(n);d.push(r)}return d},e.setup=function(){e.createCanvas(1e3,1e3),e.image(e.back_img[window.hand_index],0,0,1e3,1e3),e.image(e.bb_img[window.back_index],0,0,1e3,1e3),e.tint(window.face_color[0],window.face_color[1],window.face_color[2]),e.image(e.hand_img[window.hand_index],0,0,1e3,1e3),e.noTint(),e.image(e.elem_img[window.elem_index],0,0,1e3,1e3)},e.make_gradient=function(){c1=e.color(255*fxrand(),255*fxrand(),255*fxrand()),c2=e.color(255*fxrand(),255*fxrand(),255*fxrand());for(let n=0;n<e.height;n++){let a=e.map(n,0,e.height,0,1),o=e.lerpColor(c1,c2,a);e.stroke(o),e.line(0,n,e.width,n)}},e.mouseReleased=function(){}}),e)})();